// PlugAI project — ESP32-C3-DevKitM-1 (ESP-IDF v5.5).
// Two LEDs (LED1 red on GPIO4, LED2 green on GPIO5) + momentary button (GPIO6, internal pull-up to GND).
// Initial state: LED1 ON, LED2 OFF.
// Behaviour: the two LED states are swapped ONLY when the button is held continuously
// for at least 2 s (2000 ms). Shorter presses (e.g. 0.5 s / 1.5 s) do nothing.
// One long press performs exactly one swap; the button must be released before a
// further long press can trigger another swap (re-arm on release).

#include <stdio.h>
#include <stdint.h>

#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/gpio.h"
#include "esp_timer.h"
#include "esp_log.h"

#define LED1_GPIO   GPIO_NUM_4   // red LED, active high through 220 ohm
#define LED2_GPIO   GPIO_NUM_5   // green LED, active high through 220 ohm
#define BTN_GPIO    GPIO_NUM_6   // button to GND, internal pull-up (pressed = 0)

#define POLL_MS         10          // polling period
#define DEBOUNCE_CNT    2           // 2 consecutive LOW samples (~20 ms) = stable press
#define HOLD_US         2000000LL   // 2 s hold required to swap

void app_main(void)
{
    // ---- GPIO configuration -------------------------------------------------
    gpio_config_t out_cfg = {
        .pin_bit_mask = (1ULL << LED1_GPIO) | (1ULL << LED2_GPIO),
        .mode         = GPIO_MODE_OUTPUT,
        .pull_up_en   = GPIO_PULLUP_DISABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type    = GPIO_INTR_DISABLE,
    };
    ESP_ERROR_CHECK(gpio_config(&out_cfg));

    gpio_config_t btn_cfg = {
        .pin_bit_mask = (1ULL << BTN_GPIO),
        .mode         = GPIO_MODE_INPUT,
        .pull_up_en   = GPIO_PULLUP_ENABLE,
        .pull_down_en = GPIO_PULLDOWN_DISABLE,
        .intr_type    = GPIO_INTR_DISABLE,
    };
    ESP_ERROR_CHECK(gpio_config(&btn_cfg));

    // ---- Initial state: LED1 ON, LED2 OFF -----------------------------------
    uint8_t led1_state = 1;
    uint8_t led2_state = 0;
    gpio_set_level(LED1_GPIO, led1_state);
    gpio_set_level(LED2_GPIO, led2_state);

    printf("PlugAI: hold button >2 s to swap LEDs. LED1(GPIO4)=%d LED2(GPIO5)=%d, button GPIO6 pull-up (pressed=LOW)\n",
           led1_state, led2_state);

    // ---- Polling loop -------------------------------------------------------
    int low_cnt   = 0;        // consecutive LOW samples
    int64_t press_us = 0;     // time when the press was confirmed (0 = not timed yet)
    int fired     = 0;        // 1 once the current press has already caused a swap

    while (1) {
        int raw = gpio_get_level(BTN_GPIO);

        if (raw == 0) {
            // Button held (LOW).
            if (low_cnt < DEBOUNCE_CNT) {
                low_cnt++;
            }
            if (low_cnt >= DEBOUNCE_CNT) {
                if (press_us == 0) {
                    press_us = esp_timer_get_time();   // start of confirmed hold
                }
                int64_t hold_us = esp_timer_get_time() - press_us;
                if (!fired && hold_us >= HOLD_US) {
                    fired = 1;   // one swap per long press; stays latched until release

                    uint8_t tmp = led1_state;
                    led1_state = led2_state;
                    led2_state = tmp;

                    gpio_set_level(LED1_GPIO, led1_state);
                    gpio_set_level(LED2_GPIO, led2_state);

                    printf("SWAP (hold=%lld ms): led1=%d led2=%d\n",
                           (long long)(hold_us / 1000), led1_state, led2_state);
                }
            }
        } else {
            // Released / idle: reset the hold timer and re-arm the trigger.
            low_cnt  = 0;
            press_us = 0;
            fired    = 0;
        }

        vTaskDelay(pdMS_TO_TICKS(POLL_MS));   // feed the task watchdog
    }
}
